# ---------------------------------------------------------------- verifier plumbing
def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _grant_read(argument: str) -> None:
    """Make an agent-written path readable before the uid drop (editors leave 0600)."""
    if not argument.startswith("/app"):
        return
    path = Path(argument)
    if not path.exists():
        return
    try:
        path.chmod(path.stat().st_mode | (0o555 if path.is_dir() else 0o444))
        if path.is_dir():
            for child in path.iterdir():
                if child.is_file():
                    child.chmod(child.stat().st_mode | 0o444)
        for parent in path.parents:
            parent.chmod(parent.stat().st_mode | 0o555)
            if str(parent) == "/app":
                break
    except OSError:
        pass


def _untrusted_command(command: list[str], grant_read: bool = True) -> list[str]:
    if os.name != "posix" and _root_only_tests_present():
        raise RuntimeError("verifier isolation requires POSIX uid/gid dropping")
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        if grant_read:
            for argument in command:
                _grant_read(argument)
        return [*_SETPRIV, *command]
    return command


def _run(args: list[str], timeout: float, grant_read: bool = True) -> tuple[int | None, str]:
    """Run the delivered program in its own process group, consume its output, kill the group."""
    if not PROGRAM.is_file():
        return None, ""
    cmd = _untrusted_command([sys.executable, str(PROGRAM), *args], grant_read)
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
    try:
        _out, err = proc.communicate(timeout=timeout)
        code = proc.returncode
    except subprocess.TimeoutExpired:
        code, err = None, b""
    finally:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except OSError:
            pass
        try:
            proc.communicate(timeout=10)
        except (subprocess.SubprocessError, OSError, ValueError):
            pass
    return code, err.decode("utf-8", "replace")


def _unpack(blobs: dict[str, str], target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    for rel, b in blobs.items():
        (target / rel).write_bytes(zlib.decompress(bytes.fromhex(b)))
    return target


def _write_texts(texts: dict[str, str], target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    for name, text in texts.items():
        (target / name).write_bytes(text.encode("utf-8"))
    return target


def _open_tree(root: Path) -> None:
    for p in [root, *root.rglob("*")]:
        p.chmod(0o777 if p.is_dir() else 0o644)


def _expected() -> dict:
    with _LOCK:
        if "expected" not in _CACHE:
            _CACHE["expected"] = json.loads(zlib.decompress(bytes.fromhex(_EXPECTED_BLOB)).decode("utf-8"))
    return _CACHE["expected"]  # type: ignore[return-value]


def _tree_digest(root: Path) -> str:
    h = hashlib.sha256()
    for p in sorted(root.rglob("*")):
        h.update(str(p.relative_to(root)).encode())
        if p.is_file():
            h.update(p.read_bytes())
    return h.hexdigest()


def _read_dir(d: Path, names: list[str]) -> dict:
    out = {}
    for n in names:
        p = d / n
        try:
            out[n] = p.read_text(encoding="utf-8") if p.is_file() else None
        except (OSError, UnicodeDecodeError):
            out[n] = None
    return out


def _battery() -> dict:
    """Every run of the delivered program, done once with the shipped estate planted.

    Each run gets a private work directory holding only that run's own inputs; it is removed
    before the next run starts, so no run can read the expected results of another run.
    """
    with _LOCK:
        if "battery" in _CACHE:
            return _CACHE["battery"]  # type: ignore[return-value]
        res: dict = {"ok": False}
        _CACHE["battery"] = res
        if not PROGRAM.is_file():
            return res
        exp = _expected()
        root = Path(tempfile.mkdtemp(prefix="kestrel-grade-"))
        root.chmod(0o777)
        planted = None
        if not APP_DATA.exists():
            planted = _unpack(_SHIPPED_DATA, APP_DATA)
            _open_tree(planted)
        deadline = time.monotonic() + BATTERY_BUDGET
        try:
            runs: dict = {}
            changed = False

            def go(key, inputs, build_args, names, place=None, remove_input=None, lock_inputs=False):
                nonlocal changed
                # place reuses an earlier run's (already removed) work path, so a repeat
                # run sees exactly the same paths and only nondeterminism can differ.
                work = root / (place or key)
                staged = [(_unpack if blobs else _write_texts)(src, work / rel) for rel, blobs, src in inputs]
                work.mkdir(parents=True, exist_ok=True)
                _open_tree(work)
                if remove_input is not None:
                    (staged[0] / remove_input).unlink()
                if lock_inputs:
                    for path in staged:
                        path.chmod(0o000)
                outdir = work / "result"
                before = [_tree_digest(p) for p in staged]
                remaining = deadline - time.monotonic()
                code, err = _run(build_args(staged, work, outdir), min(RUN_TIMEOUT, remaining), not lock_inputs) if remaining > 0 else (None, "")
                runs[key] = {"code": code, "err": err, "files": _read_dir(outdir, names), "made": outdir.exists()}
                if [_tree_digest(p) for p in staged] != before:
                    changed = True
                shutil.rmtree(work, ignore_errors=True)

            estate = [("estate", True, _EVAL_DATA)]
            vis1 = ("vis/one", False, exp["visible"]["p1"])
            vis2 = ("vis/two", False, exp["visible"]["p2"])
            ev1 = ("unseen/first", False, exp["eval"]["p1"])
            ev2 = ("unseen/second", False, exp["eval"]["p2"])
            go("e1a", estate, lambda s, w, o: ["phase1", str(s[0]), str(o)], P1)
            go("e1a2", estate, lambda s, w, o: ["phase1", str(s[0]), str(o)], P1, place="e1a")
            go("e1b", [("moved/second-copy", True, _EVAL_DATA)], lambda s, w, o: ["phase1", str(s[0]), str(o)], P1)
            go("v2", [vis1], lambda s, w, o: ["phase2", str(s[0]), str(o)], P2)
            go("e2", [ev1], lambda s, w, o: ["phase2", str(s[0]), str(o)], P2)
            go("v3", [vis1, vis2], lambda s, w, o: ["phase3", str(s[0]), str(s[1]), str(o)], P3)
            go("e3", [ev1, ev2], lambda s, w, o: ["phase3", str(s[0]), str(s[1]), str(o)], P3)
            go("d2", [], lambda s, w, o: ["phase2", str(OUT / "p1"), str(o)], P2)
            go("d3", [], lambda s, w, o: ["phase3", str(OUT / "p1"), str(OUT / "p2"), str(o)], P3)
            go("bad_stage", estate, lambda s, w, o: ["phase9", str(s[0]), str(o)], P1)
            go("bad_count", [vis1], lambda s, w, o: ["phase2", str(s[0])], P2)
            go("missing_phase1", [], lambda s, w, o: ["phase1", str(w / "no-such-dir"), str(o)], P1)
            go("missing_phase2", [], lambda s, w, o: ["phase2", str(w / "no-such-dir"), str(o)], P2)
            go("missing_file_phase2", [vis1], lambda s, w, o: ["phase2", str(s[0]), str(o)], P2,
               remove_input="sensor_daily.csv")
            go("unreadable_phase2", [vis1], lambda s, w, o: ["phase2", str(s[0]), str(o)], P2,
               lock_inputs=True)
            go("missing_phase3", [vis1], lambda s, w, o: ["phase3", str(s[0]), str(w / "no-such-dir"), str(o)], P3)
            # The same stage run twice into one output directory must leave the same bytes.
            work = root / "rerun"
            staged_one = _write_texts(exp["visible"]["p1"], work / "vis" / "one")
            _open_tree(work)
            outdir = work / "result"
            rerun = []
            for _attempt in range(2):
                remaining = deadline - time.monotonic()
                code, _err = _run(["phase2", str(staged_one), str(outdir)], min(RUN_TIMEOUT, remaining)) if remaining > 0 else (None, "")
                rerun.append({"code": code, "files": _read_dir(outdir, P2)})
            runs["rerun"] = rerun
            shutil.rmtree(work, ignore_errors=True)

            work = root / "rerun3"
            staged_one = _write_texts(exp["visible"]["p1"], work / "vis" / "one")
            staged_two = _write_texts(exp["visible"]["p2"], work / "vis" / "two")
            _open_tree(work)
            outdir = work / "result"
            rerun3 = []
            for _attempt in range(2):
                remaining = deadline - time.monotonic()
                code, _err = _run(["phase3", str(staged_one), str(staged_two), str(outdir)], min(RUN_TIMEOUT, remaining)) if remaining > 0 else (None, "")
                rerun3.append({"code": code, "files": _read_dir(outdir, P3)})
            runs["rerun3"] = rerun3
            shutil.rmtree(work, ignore_errors=True)
            res.update(ok=True, runs=runs, input_changed=changed)
        finally:
            if planted is not None:
                shutil.rmtree(planted, ignore_errors=True)
            shutil.rmtree(root, ignore_errors=True)
        return res


def _holds(check) -> bool:
    try:
        return bool(check())
    except Exception:
        return False


# ---------------------------------------------------------------- reading and comparing
def _agent(rel: str) -> str:
    return (OUT / rel).read_text(encoding="utf-8")


def _rows(text: str) -> list[dict]:
    return list(csv.DictReader(io.StringIO(text)))


def _keyed(name: str, text: str) -> dict:
    return {tuple(r[k] for k in CSV_KEYS[name]): r for r in _rows(text)}


def _vis(phase: str, name: str) -> str:
    return _expected()["visible"][phase][name]


def _ev(phase: str, name: str) -> str:
    return _expected()["eval"][phase][name]


def _p1_fields(name: str, fields: list[str], exact_keys: bool = False) -> bool:
    exp = _keyed(name, _vis("p1", name))
    got = _keyed(name, _agent("p1/" + name))
    if not exp:
        return False
    if exact_keys and set(got) != set(exp):
        return False
    inter = set(exp) & set(got)
    if len(inter) * 10 < len(exp) * 9:
        return False
    return all(got[k].get(f) == exp[k][f] for k in inter for f in fields)


def _p1_subset(name: str, pred) -> bool:
    exp = sorted(tuple(r.values()) for r in _rows(_vis("p1", name)) if pred(r))
    got = sorted(tuple(r.values()) for r in _rows(_agent("p1/" + name)) if pred(r))
    return bool(exp) and got == exp


def _json(text: str):
    return json.loads(text)


def _strip_lineage(doc: dict) -> dict:
    return {k: v for k, v in doc.items() if k != "upstream_digest"}


def _run_files(key: str) -> dict:
    b = _battery()
    r = b["runs"][key]
    if r["code"] != 0:
        raise AssertionError(key)
    return r["files"]


def _run_json(key: str, name: str):
    text = _run_files(key)[name]
    if text is None:
        raise AssertionError(name)
    return json.loads(text)


def _rows_by_key(doc: dict) -> dict:
    return {(r["asset_id"], r["day"]): r for r in doc["rows"]}


def _p2_rows_field(name: str, fields: list[str]) -> bool:
    exp = _rows_by_key(_json(_vis("p2", name)))
    got = _rows_by_key(_run_json("v2", name))
    inter = set(exp) & set(got)
    if not exp or len(inter) * 10 < len(exp) * 9:
        return False
    return all(json.dumps(got[k].get(f)) == json.dumps(exp[k][f]) for k in inter for f in fields)


def _same(a, b) -> bool:
    return json.dumps(a, sort_keys=True) == json.dumps(b, sort_keys=True)


def _visible_only_ids() -> set:
    with _LOCK:
        if "vis_ids" not in _CACHE:
            vis = {r["asset_id"] for r in _rows(_vis("p1", "asset_registry.csv"))}
            ev = {r["asset_id"] for r in _rows(_ev("p1", "asset_registry.csv"))}
            _CACHE["vis_ids"] = vis - ev
    return _CACHE["vis_ids"]  # type: ignore[return-value]


def _carries_visible_ids(files: dict) -> bool:
    ids = _visible_only_ids()
    blob = "".join(t or "" for t in files.values())
    return bool(blob) and any(i in blob for i in ids)


def _error_exit(key: str, want: int) -> bool:
    r = _battery()["runs"][key]
    lines = [x for x in r["err"].splitlines() if x.strip()]
    nothing = not any(v is not None for v in r["files"].values())
    return r["code"] == want and len(lines) == 1 and lines[0].startswith("error:") and nothing


# ---------------------------------------------------------------- detectors
def _hardcoded() -> bool:
    try:
        text = PROGRAM.read_text(encoding="utf-8", errors="replace")
    except OSError:
        text = ""
    ids = sorted(_visible_only_ids())
    digests = [s["digest"] for s in _json(_vis("p1", "run_parameters.json"))["sources"]]
    embedded = sum(1 for i in ids if i in text) >= 25 or any(d in text for d in digests)
    return embedded


# ---------------------------------------------------------------- phase 1 checks
def _check_p1_layout() -> bool:
    for name, header in CSV_HEADERS.items():
        raw = (OUT / "p1" / name).read_bytes()
        if b"\r" in raw or not raw.endswith(b"\n"):
            return False
        text = raw.decode("utf-8")
        if text.split("\n", 1)[0] != header:
            return False
        keys = [tuple(r[k] for k in CSV_KEYS[name]) for r in _rows(text)]
        if not keys or keys != sorted(keys):
            return False
    text = _agent("p1/run_parameters.json")
    return text == json.dumps(json.loads(text), indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def _check_json_layout() -> bool:
    for phase, names in (("p2", P2), ("p3", P3)):
        for n in names:
            text = _agent(f"{phase}/{n}")
            if text != json.dumps(json.loads(text), indent=2, sort_keys=True, ensure_ascii=False) + "\n":
                return False
    return True


def _check_attestation(role: str | None, fields: list[str]) -> bool:
    exp = {s["file"]: s for s in _json(_vis("p1", "run_parameters.json"))["sources"]}
    got = {s["file"]: s for s in _json(_agent("p1/run_parameters.json"))["sources"]}
    want = {f: s for f, s in exp.items() if role is None or s["role"] == role}
    return bool(want) and all(f in got and all(_same(got[f].get(k), s[k]) for k in fields) for f, s in want.items())


def _check_run_parameters() -> bool:
    exp, got = _json(_vis("p1", "run_parameters.json")), _json(_agent("p1/run_parameters.json"))
    return all(_same(got.get(k), exp[k]) for k in ("run_id", "freeze", "telemetry_window", "parameters", "holdout_assets", "regions"))


def _check_eval_tables(names: list[str]) -> bool:
    files = _run_files("e1a")
    for n in names:
        if files[n] is None:
            return False
        if n.endswith(".csv"):
            if _rows(files[n]) != _rows(_ev("p1", n)):
                return False
        elif not _same(json.loads(files[n]), json.loads(_ev("p1", n))):
            return False
    return True


# ---------------------------------------------------------------- phase 2 and 3 checks
def _check_program_docs(key: str, phase: str, names: list[str], fields: list[str] | None, tier: str = "visible") -> bool:
    for n in names:
        got = _run_json(key, n)
        exp = _json(_expected()[tier][phase][n])
        keys = fields if fields is not None else list(exp)
        if not all(k in got and _same(got[k], exp[k]) for k in keys):
            return False
    return True


def _check_declared_matches(key: str, phase: str, names: list[str]) -> bool:
    files = _run_files(key)
    for n in names:
        mine = _json(_agent(f"{phase}/{n}"))
        theirs = files[n]
        if theirs is None or not _same(_strip_lineage(mine), _strip_lineage(json.loads(theirs))):
            return False
    return True


def _check_sample_keys() -> bool:
    exp = set(_rows_by_key(_json(_vis("p2", "label_table.json"))))
    got = set(_rows_by_key(_run_json("v2", "label_table.json")))
    return bool(exp) and got == exp


def _check_eval_section(section: str, fields: list[str]) -> bool:
    exp = _json(_vis("p3", "baseline_metrics.json"))[section]
    got = _run_json("v3", "baseline_metrics.json")[section]
    return all(k in got and _same(got[k], exp[k]) for k in fields)


def _check_z(field: str) -> bool:
    exp = _rows_by_key(_json(_vis("p3", "train_ready.json")))
    got = _rows_by_key(_run_json("v3", "train_ready.json"))
    inter = set(exp) & set(got)
    if not exp or len(inter) * 10 < len(exp) * 9:
        return False
    return all(_same(got[k].get(field), exp[k][field]) for k in inter)


# ---------------------------------------------------------------- negative detectors (true when the cheat happened)
def _check_negative_filename() -> bool:
    r = _battery()["runs"]
    a, a2, b = r["e1a"], r["e1a2"], r["e1b"]
    return a["code"] == 0 and b["code"] == 0 and a["files"] == a2["files"] and a["files"] != b["files"]


def _check_negative_nondeterministic() -> bool:
    r = _battery()["runs"]
    return r["e1a"]["code"] == 0 and r["e1a2"]["code"] == 0 and r["e1a"]["files"] != r["e1a2"]["files"]


def _check_negative_corpus() -> bool:
    if _hardcoded():
        return False
    return _carries_visible_ids(_battery()["runs"]["e1a"]["files"])


def _check_negative_downstream_corpus() -> bool:
    if _hardcoded():
        return False
    r = _battery()["runs"]
    if _carries_visible_ids(r["e1a"]["files"]):
        return False
    mixed2 = _carries_visible_ids(r["e2"]["files"]) and r["e2"]["files"] != r["v2"]["files"]
    mixed3 = _carries_visible_ids(r["e3"]["files"]) and r["e3"]["files"] != r["v3"]["files"]
    return mixed2 or mixed3


def _check_negative_ignores_upstream() -> bool:
    if _hardcoded():
        return False
    r = _battery()["runs"]
    same2 = r["e2"]["code"] == 0 and r["e2"]["files"]["label_table.json"] is not None and r["e2"]["files"] == r["v2"]["files"]
    same3 = r["e3"]["code"] == 0 and r["e3"]["files"]["train_ready.json"] is not None and r["e3"]["files"] == r["v3"]["files"]
    return same2 or same3


def _check_negative_unbound_digests() -> bool:
    runs = _battery()["runs"]
    for key, phase, names in (("d2", "p2", P2), ("d3", "p3", P3)):
        r = runs[key]
        if r["code"] != 0:
            continue
        for n in names:
            produced = r["files"].get(n)
            if produced is None:
                continue
            try:
                stated = json.loads((OUT / phase / n).read_text(encoding="utf-8")).get("upstream_digest")
                program = json.loads(produced).get("upstream_digest")
            except (OSError, ValueError, AttributeError):
                continue
            if isinstance(stated, str) and stated and isinstance(program, str) and program and stated != program:
                return True
    return False


def _check_rerun_same_output(key: str, names: list[str]) -> bool:
    first, second = _battery()["runs"][key]
    complete = all(v is not None for v in first["files"].values())
    return set(first["files"]) == set(names) and first["code"] == 0 and second["code"] == 0 and complete and first["files"] == second["files"]


def _check_negative_modifies_input() -> bool:
    b = _battery()
    return bool(b.get("ok") and b["input_changed"])


# ---------------------------------------------------------------- exact release checks
def _delivered_exact(phase: str, names: list[str]) -> bool:
    return all(_agent(f"{phase}/{name}") == _expected()["visible"][phase][name] for name in names)


def _run_exact(key: str, phase: str, names: list[str]) -> bool:
    files = _run_files(key)
    return all(files.get(name) == _expected()["eval"][phase][name] for name in names)


# ---------------------------------------------------------------- criteria
@criterion(description="The delivered phase 1 directory contains the exact six phase 1 files fixed by FPS-4 and the output contract.")
def delivered_phase1_outputs(workspace: Path) -> bool:
    return _holds(lambda: _delivered_exact("p1", P1))


@criterion(description="On the unseen estate phase 1 writes the exact six phase 1 files.")
def unseen_phase1_outputs(workspace: Path) -> bool:
    return _holds(lambda: _run_exact("e1b", "p1", P1))


@criterion(description="The delivered phase 2 directory contains the exact six phase 2 files derived from the required phase 1 release.")
def delivered_phase2_outputs(workspace: Path) -> bool:
    return _holds(lambda: _delivered_exact("p2", P2))


@criterion(description="On the unseen phase 1 directory phase 2 writes the exact six phase 2 files.")
def unseen_phase2_outputs(workspace: Path) -> bool:
    return _holds(lambda: _run_exact("e2", "p2", P2))


@criterion(description="The delivered phase 3 directory contains the exact six phase 3 files derived from the required upstream release.")
def delivered_phase3_outputs(workspace: Path) -> bool:
    return _holds(lambda: _delivered_exact("p3", P3))


@criterion(description="On the unseen upstream directories phase 3 writes the exact six phase 3 files.")
def unseen_phase3_outputs(workspace: Path) -> bool:
    return _holds(lambda: _run_exact("e3", "p3", P3))


@criterion(description="An unknown stage and a wrong directory count each exit 2 with one error line and no output.")
def usage_error_exits(workspace: Path) -> bool:
    return _holds(lambda: _error_exit("bad_stage", 2) and _error_exit("bad_count", 2))


@criterion(description="A missing phase 1 input directory exits 3 with one error line and no output.")
def missing_phase1_input_exits(workspace: Path) -> bool:
    return _holds(lambda: _error_exit("missing_phase1", 3))


@criterion(description="A missing phase 2 upstream directory exits 3 with one error line and no output.")
def missing_phase2_upstream_exits(workspace: Path) -> bool:
    return _holds(lambda: _error_exit("missing_phase2", 3))


@criterion(description="A phase 2 upstream directory lacking a required file exits 3 with one error line and no output.")
def incomplete_phase2_upstream_exits(workspace: Path) -> bool:
    return _holds(lambda: _error_exit("missing_file_phase2", 3))


@criterion(description="An unreadable phase 2 upstream directory exits 3 with one error line and no output.")
def unreadable_phase2_upstream_exits(workspace: Path) -> bool:
    return _holds(lambda: _error_exit("unreadable_phase2", 3))


@criterion(description="A missing phase 3 upstream directory exits 3 with one error line and no output.")
def missing_phase3_upstream_exits(workspace: Path) -> bool:
    return _holds(lambda: _error_exit("missing_phase3", 3))


@criterion(description="A second phase 2 run into the same output directory exits 0 and leaves the same six files byte for byte.")
def rerun_into_same_output_directory(workspace: Path) -> bool:
    return _holds(lambda: _check_rerun_same_output("rerun", P2))


@criterion(description="A second phase 3 run into the same output directory exits 0 and leaves the same six files byte for byte.")
def rerun_phase3_into_same_output_directory(workspace: Path) -> bool:
    return _holds(lambda: _check_rerun_same_output("rerun3", P3))


@criterion(description="The program source embeds asset ids or attestation digests that exist only in the shipped estate.")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # Holds when the cheat happened; the negative weight does the punishing.
    return _holds(lambda: _hardcoded())


@criterion(description="Two phase 1 runs on the same estate write different bytes.")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # Holds when the cheat happened; the negative weight does the punishing.
    return _holds(lambda: _check_negative_nondeterministic())


@criterion(description="Phase 2 or phase 3 writes the same results for two different upstream directories.")
def negative_stage_output_ignores_upstream_directory(workspace: Path) -> bool:
    # Holds when the cheat happened; the negative weight does the punishing.
    return _holds(lambda: _check_negative_ignores_upstream())


@criterion(description="The program changes files inside a directory it was given to read.")
def negative_modifies_input_directory(workspace: Path) -> bool:
    # Holds when the cheat happened; the negative weight does the punishing.
    return _holds(lambda: _check_negative_modifies_input())


criteria.delivered_phase1_outputs(weight=5)
criteria.unseen_phase1_outputs(weight=5)
criteria.delivered_phase2_outputs(weight=5)
criteria.unseen_phase2_outputs(weight=5)
criteria.delivered_phase3_outputs(weight=5)
criteria.unseen_phase3_outputs(weight=5)
criteria.usage_error_exits(weight=1)
criteria.missing_phase1_input_exits(weight=1)
criteria.missing_phase2_upstream_exits(weight=1)
criteria.incomplete_phase2_upstream_exits(weight=1)
criteria.unreadable_phase2_upstream_exits(weight=1)
criteria.missing_phase3_upstream_exits(weight=1)
criteria.rerun_into_same_output_directory(weight=1)
criteria.rerun_phase3_into_same_output_directory(weight=1)
criteria.negative_hardcoded_sample_answers(weight=-5)
criteria.negative_nondeterministic_output(weight=-3)
criteria.negative_stage_output_ignores_upstream_directory(weight=-5)
criteria.negative_modifies_input_directory(weight=-3)
